<?php
declare(strict_types=1); namespace App\Controllers\Web; use App\Controllers\BaseController; use CodeIgniter\Exceptions\PageNotFoundException;
final class BrandAssetController extends BaseController { public function show(string $id){$host=strtolower(preg_replace('/:\d+$/','',$this->request->getServer('HTTP_HOST')??''));$a=db_connect()->table('shop_brand_assets a')->select('a.storage_key,a.mime_type')->join('shop_domains d','d.tenant_id=a.tenant_id AND d.shop_id=a.shop_id')->where(['a.public_id'=>$id,'a.is_active'=>1,'d.hostname'=>$host,'d.is_active'=>1,'d.verification_status'=>'VERIFIED'])->get()->getRowArray();$path=$a?WRITEPATH.'uploads/branding/'.$a['storage_key']:'';if(!$a||!is_file($path))throw PageNotFoundException::forPageNotFound();return $this->response->setHeader('Content-Type',$a['mime_type'])->setHeader('Cache-Control','public,max-age=31536000,immutable')->setBody(file_get_contents($path));}}
